public class DiamondPrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String capture(int size) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            DiamondPrinter.printDiamond(size);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("printDiamond(1)", "*\n", capture(1));
        check("printDiamond(2)", " *\n***\n *\n", capture(2));
        check("printDiamond(3)", "  *\n ***\n*****\n ***\n  *\n", capture(3));
        check("printDiamond(4)",
                "   *\n  ***\n *****\n*******\n *****\n  ***\n   *\n", capture(4));
        check("printDiamond(0) prints nothing", "", capture(0));
        check("printDiamond(-2) prints nothing", "", capture(-2));

        String five = capture(5);
        String[] lines = five.split("\n", -1);
        check("printDiamond(5) row count", 9, lines.length - 1);
        check("printDiamond(5) widest row", "*********", lines.length > 4 ? lines[4] : "");
        check("printDiamond(5) last row has no trailing space", "    *", lines.length > 8 ? lines[8] : "");

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

